from collections import Counter


def can_chain(dominoes):
    """Return a chain of all the given dominoes, or None if no chain exists.

    A valid chain uses every domino exactly once (a stone may be flipped),
    has matching ends between neighbouring stones, and the free ends of
    the first and last stones match each other.
    """
    if not dominoes:
        return []

    # A domino chain is an Eulerian circuit in the multigraph whose edges
    # are the dominoes, so every value must have even degree and every
    # value must lie in a single connected component.
    counts = Counter()
    for a, b in dominoes:
        counts[a] += 1
        counts[b] += 1
    if any(n % 2 for n in counts.values()):
        return None

    neighbours = {}
    for a, b in dominoes:
        neighbours.setdefault(a, set()).add(b)
        neighbours.setdefault(b, set()).add(a)
    start = next(iter(counts))
    seen = {start}
    stack = [start]
    while stack:
        value = stack.pop()
        for other in neighbours.get(value, ()):
            if other not in seen:
                seen.add(other)
                stack.append(other)
    if seen != set(counts):
        return None

    first = dominoes[0]
    remaining = dominoes[1:]

    def search(last, remaining, chain):
        if not remaining:
            return chain if last == chain[0][0] else None
        for i, (a, b) in enumerate(remaining):
            if a == last:
                rest = remaining[:i] + remaining[i + 1:]
                result = search(b, rest, chain + [(a, b)])
                if result is not None:
                    return result
            elif b == last:
                rest = remaining[:i] + remaining[i + 1:]
                result = search(a, rest, chain + [(b, a)])
                if result is not None:
                    return result
        return None

    return search(first[1], remaining, [first])
